-- Exact function-body checks in addition to migration ledger, trigger, columns and permissions.
WITH checks(name,ok) AS (
 SELECT 'ledger',EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261104000000' AND name='question_practice_continuous' AND cardinality(statements)=1 AND md5(statements[1])='879152a69b80d775fdae4454bfeda346')
 UNION ALL SELECT 'question_practice_reject_ended' AS name,coalesce((SELECT md5(prosrc)='76319706dd67a6134d2a1106a3375e0b' AND prosecdef=false AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_reject_ended()')),false) AS ok
 UNION ALL SELECT 'question_practice_topic_status' AS name,coalesce((SELECT md5(prosrc)='87bfa6d1ad3249b4e5158346fc19c08e' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_topic_status(uuid)')),false) AS ok
 UNION ALL SELECT 'question_practice_continuous_pool' AS name,coalesce((SELECT md5(prosrc)='76cabebb298c016f1cf88728997b8a01' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_continuous_pool(uuid)')),false) AS ok
 UNION ALL SELECT 'question_practice_issue_next' AS name,coalesce((SELECT md5(prosrc)='6ad432419c04b73b763410f80231fc72' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_issue_next(uuid)')),false) AS ok
 UNION ALL SELECT 'question_practice_continuous_state' AS name,coalesce((SELECT md5(prosrc)='5765991cdb57155b535bed5bb3a5259e' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_continuous_state(uuid)')),false) AS ok
 UNION ALL SELECT 'question_practice_snapshot' AS name,coalesce((SELECT md5(prosrc)='75620c466e8819f8f4ae007d71e034cc' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_snapshot(uuid)')),false) AS ok
 UNION ALL SELECT 'start_continuous_question_practice' AS name,coalesce((SELECT md5(prosrc)='b326cc1c22c94da56ab0d668810e09cb' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.start_continuous_question_practice(uuid,uuid,uuid)')),false) AS ok
 UNION ALL SELECT 'next_continuous_question_practice' AS name,coalesce((SELECT md5(prosrc)='350fec3acf4af28b5e6f1b19df1e8668' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.next_continuous_question_practice(uuid)')),false) AS ok
 UNION ALL SELECT 'end_continuous_question_practice' AS name,coalesce((SELECT md5(prosrc)='75a0340a75c139de6dcb2dbe771308da' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.end_continuous_question_practice(uuid)')),false) AS ok
 UNION ALL SELECT 'get_open_continuous_question_practice' AS name,coalesce((SELECT md5(prosrc)='7bfe2c07b97fb8cc444eb4f49c7b8cd2' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_open_continuous_question_practice()')),false) AS ok
 UNION ALL SELECT 'start_continuous_question_practice_privileges',has_function_privilege('authenticated','public.start_continuous_question_practice(uuid,uuid,uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.start_continuous_question_practice(uuid,uuid,uuid)','EXECUTE')
 UNION ALL SELECT 'next_continuous_question_practice_privileges',has_function_privilege('authenticated','public.next_continuous_question_practice(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.next_continuous_question_practice(uuid)','EXECUTE')
 UNION ALL SELECT 'end_continuous_question_practice_privileges',has_function_privilege('authenticated','public.end_continuous_question_practice(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.end_continuous_question_practice(uuid)','EXECUTE')
 UNION ALL SELECT 'get_open_continuous_question_practice_privileges',has_function_privilege('authenticated','public.get_open_continuous_question_practice()','EXECUTE') AND NOT has_function_privilege('anon','public.get_open_continuous_question_practice()','EXECUTE')
 UNION ALL SELECT 'question_practice_topic_status_private',NOT has_function_privilege('authenticated','public.question_practice_topic_status(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_topic_status(uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_continuous_pool_private',NOT has_function_privilege('authenticated','public.question_practice_continuous_pool(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_continuous_pool(uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_issue_next_private',NOT has_function_privilege('authenticated','public.question_practice_issue_next(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_issue_next(uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_continuous_state_private',NOT has_function_privilege('authenticated','public.question_practice_continuous_state(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_continuous_state(uuid)','EXECUTE')
 UNION ALL SELECT 'ended_trigger',EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='question_practice_reject_ended' AND tgrelid='public.question_practice_attempts'::regclass AND tgenabled='O')
 UNION ALL SELECT 'session_columns',(SELECT count(*)=2 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_practice_sessions' AND column_name IN ('mode','ended_at'))
 UNION ALL SELECT 'item_columns',(SELECT count(*)=2 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_practice_items' AND column_name IN ('issued_at','selection_reason'))
 UNION ALL SELECT 'position_limit',EXISTS(SELECT 1 FROM pg_constraint WHERE conname='question_practice_items_position_check' AND pg_get_constraintdef(oid) LIKE '%100%')
 UNION ALL SELECT 'attempts_read_only',NOT has_table_privilege('authenticated','public.question_practice_attempts','INSERT,UPDATE,DELETE')
 UNION ALL SELECT 'sessions_read_only',NOT has_table_privilege('authenticated','public.question_practice_sessions','INSERT,UPDATE,DELETE')
 UNION ALL SELECT 'items_read_only',NOT has_table_privilege('authenticated','public.question_practice_items','INSERT,UPDATE,DELETE')
) SELECT jsonb_build_object('all_checks_pass',bool_and(ok),'checks',jsonb_agg(jsonb_build_object('name',name,'ok',ok) ORDER BY name)) AS continuous_practice_verification FROM checks;
